using System.Linq;using UnityEngine;
public static class InspectRoadBlockage{public static object Main(){var c=Object.FindAnyObjectByType<ForestRoadBlockages>();c.Generate(7);return c.GetComponentsInChildren<FallenTreeObstacle>().Select(o=>new{ name=o.name,pos=o.transform.position.ToString(),scale=o.transform.localScale.ToString(),parts=o.GetComponentsInChildren<MeshCollider>().Where(m=>m.enabled).Select(m=>new{name=m.name,bounds=m.bounds.ToString(),local=m.sharedMesh.bounds.ToString(),pos=m.transform.localPosition.ToString(),rotation=m.transform.localEulerAngles.ToString()}).ToArray()}).ToArray();}}
